return $input.all().map(entry => {
  const item = entry.json;
  const isOffline = item.alert_event === 'OFFLINE';

  const lastSeenStr = item.last_seen_at 
    ? new Date(item.last_seen_at).toLocaleString('ar-EG', { timeZone: 'Africa/Cairo' })
    : 'غير محدد';

  let text = '';
  if (isOffline) {
    text = '🚨 <b>إنذار أمني حرج: انقطاع اتصال الراوتر بالكامل!</b>\n\n' +
      '🖥️ الجهاز: <code>' + item.router_id + '</code>\n' +
      '⚠️ الحالة: <b>غير متصل (OFFLINE / Dead Man\'s Switch)</b>\n' +
      '⏱️ مدة الانقطاع: <b>' + item.minutes_since_last_seen + ' دقيقة</b>\n' +
      '📅 آخر ظهور مرصود: <code>' + lastSeenStr + '</code>\n\n' +
      '🚨 <i>توقف الراوتر عن إرسال قراءات الترافيك تماماً، يرجى فحص مزود الطاقة (UPS/Power)، كابلات الشبكة، أو مزودات الخدمة.</i>';
  } else {
    text = '✅ <b>استعادة اتصال الراوتر وعودة الخدمة</b>\n\n' +
      '🖥️ الجهاز: <code>' + item.router_id + '</code>\n' +
      '📶 الحالة: <b>متصل وطبيعي (BACK ONLINE)</b>\n' +
      '📅 وقت الاستعادة: <code>' + new Date().toLocaleString('ar-EG', { timeZone: 'Africa/Cairo' }) + '</code>\n\n' +
      'ℹ️ <i>تم استئناف استلام بيانات الترافيك والكوتا من الراوتر بنجاح.</i>';
  }

  return {
    json: {
      ...item,
      telegram_message: text
    }
  };
});
